@layer hj.components {
  /* Customise: --hj-card-radius · --hj-card-padding · --hj-card-media-size (horizontal) */
  .hj-card {
    position: relative;
    display: flex;
    flex-direction: column;
    min-width: 0;
    overflow: hidden;
    border-radius: var(--hj-card-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    text-align: left;
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      background-color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-card[data-pressable] {
    cursor: pointer;
  }
  /* depth is a paper step, never a shadow */
  .hj-card[data-pressable]:hover {
    background: var(--hj-surface-2);
  }
  .hj-card[data-pressable]:active {
    transform: scale(var(--hj-press));
    transition-duration: 70ms, var(--hj-dur-base);
  }
  .hj-card[data-pressable]:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: 2px;
  }

  .hj-card-media {
    position: relative;
    flex: none;
    aspect-ratio: var(--_ratio, 16 / 9);
    overflow: hidden;
    background: var(--hj-bg-soft);
  }
  .hj-card-media > img,
  .hj-card-media > video {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .hj-card[data-orientation='horizontal'] {
    flex-direction: row;
    align-items: center;
  }
  .hj-card[data-orientation='horizontal'] > .hj-card-media {
    width: var(--hj-card-media-size, 88px);
    margin: calc(8px * var(--hj-density)) 0 calc(8px * var(--hj-density))
      calc(8px * var(--hj-density));
    border-radius: calc(var(--hj-card-radius, var(--hj-radius-md)) - 6px);
    corner-shape: var(--hj-corner-shape, round);
  }

  .hj-card-body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: calc(4px * var(--hj-density));
    min-width: 0;
    padding: var(
      --hj-card-padding,
      calc(14px * var(--hj-density)) calc(16px * var(--hj-density)) calc(16px * var(--hj-density))
    );
  }
  .hj-card-eyebrow {
    margin: 0 0 2px;
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
  }
  .hj-card-title {
    margin: 0;
    font: var(--hj-type-heading);
    letter-spacing: var(--hj-tracking-heading);
    overflow-wrap: anywhere;
  }
  .hj-card-description {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }
  .hj-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: calc(8px * var(--hj-density));
    padding: 0 calc(16px * var(--hj-density)) calc(14px * var(--hj-density));
    font-size: 12.5px;
    color: var(--hj-fg-mute);
    font-variant-numeric: tabular-nums;
  }
  .hj-card[data-orientation='horizontal'] .hj-card-footer {
    padding: 0 calc(16px * var(--hj-density)) 0 0;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export interface RootOwnProps {
  /**
   * The whole card is one target: hover steps up a paper, press dips to .97. Render it as a
   * link or button (`render={<a href="…" />}`) so it is reachable and announced.
   */
  pressable?: boolean;
  /** vertical = media on top · horizontal = a compact row with square media. @default 'vertical' */
  orientation?: 'vertical' | 'horizontal';
}
export interface RootProps extends RootOwnProps, Omit<React.ComponentProps<'div'>, 'className'> {
  className?: string;
  render?: useRender.RenderProp;
}

/** A surface for one thing: an album, an episode, an article. Not a layout tool. */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    pressable = false,
    orientation = 'vertical',
    render,
    className,
    ...rest
  } = withDefaults(config, 'Card.Root', props);
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      'data-pressable': flag(pressable),
      'data-orientation': orientation,
      className: cls(config, 'Card.Root', 'hj-card', className) as string | undefined,
    },
  });
}

export interface MediaOwnProps {
  /** Aspect ratio of the media. @default '16:9' (hanji card media) */
  ratio?: '16:9' | '4:3' | '1:1' | '3:4';
}
export interface MediaProps extends MediaOwnProps, ElementPartProps<'div'> {}

const RATIO: Readonly<Record<NonNullable<MediaOwnProps['ratio']>, string>> = {
  '16:9': '16 / 9',
  '4:3': '4 / 3',
  '1:1': '1 / 1',
  '3:4': '3 / 4',
};

/** Image or art, full bleed. Put an `<img>` (object-fit: cover) or any art inside. */
export function Media(props: MediaProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    ratio = '16:9',
    render,
    className,
    style,
    ...rest
  } = withDefaults(config, 'Card.Media', props);
  const merged = { '--_ratio': RATIO[ratio], ...style } as React.CSSProperties;
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      style: merged,
      className: cls(config, 'Card.Media', 'hj-card-media', className) as string | undefined,
    },
  });
}

export const Body: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Card.Body',
  'hj-card-body',
);
/** Optional small label above the title. */
export const Eyebrow: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Card.Eyebrow',
  'hj-card-eyebrow',
);
export const Title: (props: ElementPartProps<'h3'>) => React.ReactElement = elementPart(
  'h3',
  'Card.Title',
  'hj-card-title',
);
export const Description: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Card.Description',
  'hj-card-description',
);
/** Meta row at the bottom: counts, time, a quiet action. */
export const Footer: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Card.Footer',
  'hj-card-footer',
);

export * as Card from './card.tsx';
export type {
  MediaOwnProps as CardMediaOwnProps,
  MediaProps as CardMediaProps,
  RootOwnProps as CardRootOwnProps,
  RootProps as CardRootProps,
} from './card.tsx';
